-- Original NumPy2.5.3 conversion/creation states; no Python runtime.
-- NumPy float128 is LuaRay longdouble on this tested native ABI.
local np=require('luaray_core')
local cases,checks=0,0
local function eq(a,b,label)
 checks=checks+1
 if type(b)=='table' then
  assert(type(a)=='table' and #a==#b,label..': shape')
  for i=1,#b do eq(a[i],b[i],label..'['..i..']') end
 elseif type(b)=='userdata' then eq(a.real,b.real,label..'.real');eq(a.imag,b.imag,label..'.imag')
 elseif type(b)=='number' and b~=b then assert(a~=a,label..': NaN')
 else assert(a==b,label..': '..tostring(a)..' != '..tostring(b)) end
end

do
local function chunk()
-- 1: empty/0/dtypeNone/orderC/fill1
do
local shape=0
local ok,result=pcall(function() return np.empty(shape,{order="C"}) end)
assert(ok==true,"empty/0/dtypeNone/orderC/fill1: acceptance"..": "..tostring(result))
eq(result.shape,{0},"empty/0/dtypeNone/orderC/fill1: uninitialized result: shape")
eq(result.strides,{0},"empty/0/dtypeNone/orderC/fill1: uninitialized result: strides")
eq(result.dtype,"float64","empty/0/dtypeNone/orderC/fill1: uninitialized result: dtype")
local write_ok=pcall(function()np.copyto(result,1,"unsafe")end)
eq(write_ok,true,"empty/0/dtypeNone/orderC/fill1: writable scalar fill")
eq(result:tolist(),{},"empty/0/dtypeNone/orderC/fill1: filled result: values")
eq(result.shape,{0},"empty/0/dtypeNone/orderC/fill1: filled result: shape")
eq(result.strides,{0},"empty/0/dtypeNone/orderC/fill1: filled result: strides")
eq(result.dtype,"float64","empty/0/dtypeNone/orderC/fill1: filled result: dtype")
cases=cases+1
end
