eq(result.shape,{0,3},"full/(0, 3)/dtypeU/orderC/fill(1+0.5j): filled result: shape")
eq(result.strides,{0,0},"full/(0, 3)/dtypeU/orderC/fill(1+0.5j): filled result: strides")
eq(result.dtype,"<U1","full/(0, 3)/dtypeU/orderC/fill(1+0.5j): filled result: dtype")
cases=cases+1
end
end
chunk()
end
assert(cases==1461)
print('dense_creation107 differential: '..cases..' cases, '..checks..' checks passed')
